150	{
151	    (void)pvParameters;
152	    uint8_t prev_state = 0;
153	
154	    for (;;) {
155	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1 : 0;
156	        if (state && !prev_state) {
157	            uint32_t msg = 1;
158	            if (xButtonQueue != NULL) {
159	                xQueueSend(xButtonQueue, &msg, 0);
