        UI_ShowMainScreen();
    }
}

ui_screen_t UI_GetCurrentScreen(void)
{
    return current_screen;
}

int UI_HandleTouch(uint16_t x, uint16_t y)
{
    /* Kiem tra cham trong vung nut bam.
     * Nut bam dat tai BTN_X = 240..560.
     * Theo truc Y: BTN_Y = 395..445 (hoac 35..85 neu toa do Y bi lat).
     */
    int in_x = (x >= (BTN_X - 40) && x <= (BTN_X + BTN_WIDTH + 40));
    int in_y = ((y >= (BTN_Y - 30) && y <= (BTN_Y + BTN_HEIGHT + 30)) ||
                (y >= 10 && y <= 110));

    if (in_x && in_y) {
        UI_ToggleScreen();
        return 1;
    }
    return 0;
}

